// Parse Claude reply and validate totals
const text = $json.content?.[0]?.text ?? '';
let data;
try {
  data = JSON.parse(text.replace(/^```json\s*|```$/g, '').trim());
} catch (e) {
  return [{ json: { status: 'parse_error', raw: text } }];
}
const lineSum = (data.lines || []).reduce((s, l) => s + (l.qty || 0) * (l.unit_price || 0), 0);
const expected = lineSum + (data.tax || 0);
const diff = data.total ? Math.abs(expected - data.total) / data.total : 1;
return [{ json: { ...data, line_sum: Math.round(lineSum * 100) / 100, status: diff <= 0.01 ? 'ok' : 'needs_review' } }];
